<template>
  <v-app v-if="authenticated" :theme="darkMode ? 'pocketwiseDark' : 'pocketwise'">
    <v-app-bar class="topbar header-bar" color="background" flat height="87">
      <div class="header-content">
        <v-app-bar-nav-icon v-if="isMobile" @click="drawerOpen = !drawerOpen" />
        <div class="mobile-brand" v-if="isMobile"><div class="brand-mark">P</div><strong>Pocketwise</strong></div>
        <div class="breadcrumb" v-else><span>Workspace</span><span>/</span><strong>Overview</strong></div>
        <v-spacer />
        <v-tooltip text="Toggle theme" location="bottom"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-theme-light-dark" variant="text" aria-label="Toggle theme" @click="toggleTheme" /></template></v-tooltip>
        <v-tooltip text="Notifications" location="bottom"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-bell-outline" variant="text" aria-label="Notifications" class="notification"><i></i></v-btn></template></v-tooltip>
      </div>
    </v-app-bar>
    <v-navigation-drawer :model-value="isMobile ? drawerOpen : true" :permanent="!isMobile" color="primary" width="236" @update:model-value="drawerOpen = $event">
      <div class="drawer-content">
        <div class="brand">
          <div class="brand-mark">P</div>
          <div><strong>Pocketwise</strong><span>personal finance</span></div>
        </div>
        <v-list class="nav-list" bg-color="transparent" nav density="comfortable">
          <v-list-item class="nav-link" :active="activeSection === 'overview'" prepend-icon="mdi-home-outline" title="Overview" @click.stop.prevent="scrollToSection('overview')" />
          <v-list-item class="nav-link" :active="activeSection === 'insights'" prepend-icon="mdi-chart-donut" title="Insights" @click.stop.prevent="scrollToSection('insights')" />
          <v-list-item class="nav-link" :active="activeSection === 'transactions'" prepend-icon="mdi-arrow-top-right" title="Transactions" :subtitle="`${expenses.length} entries`" @click.stop.prevent="scrollToSection('transactions')" />
        </v-list>
        <div class="drawer-bottom">
          <div class="tip-card"><v-icon color="secondary" size="18">mdi-shimmer</v-icon><p><strong>Small steps.</strong><br />Better habits.</p><div class="tip-line"></div></div>
          <div class="profile-area">
            <button class="profile profile-button" type="button" :aria-expanded="profileMenuOpen" @click="openProfileMenu"><v-avatar color="#bf9080" size="32"><span>{{ initials }}</span></v-avatar><div><strong>{{ profile.name }}</strong><span>{{ profile.account_label }}</span></div><v-icon class="ml-auto" size="17">{{ profileMenuOpen ? 'mdi-chevron-down' : 'mdi-dots-horizontal' }}</v-icon></button>
            <v-expand-transition><div v-if="profileMenuOpen" class="profile-inline-panel"><div class="profile-menu-heading"><v-avatar color="#bf9080" size="36"><span>{{ initials }}</span></v-avatar><div><strong>{{ profile.email || profile.name }}</strong><span>Account settings</span></div></div><v-text-field v-model.trim="profileForm.name" label="Your name" density="compact" hide-details="auto" /><v-text-field v-model.trim="profileForm.account_label" label="Account label" density="compact" hide-details="auto" /><p v-if="profileError" class="form-error">{{ profileError }}</p><div class="profile-menu-actions"><v-btn color="error" variant="text" size="small" @click="logout">Sign out</v-btn><v-spacer /><v-btn color="primary" size="small" :loading="profileSaving" @click="saveProfile">Save</v-btn></div></div></v-expand-transition>
          </div>
        </div>
      </div>
    </v-navigation-drawer>

    <v-main>
      <v-progress-linear v-if="loading" class="loading-bar" color="secondary" indeterminate height="2" />
      <v-container class="main-content" fluid>

        <section class="page-heading">
          <div><p class="eyebrow">{{ greeting }}, {{ firstName }} <span class="wave">✦</span></p><h1>Your money, <em>in focus.</em></h1><p class="heading-copy">A clearer view of where your money goes, one entry at a time.</p></div>
          <v-btn color="primary" prepend-icon="mdi-plus" size="large" @click="openAddModal">Add expense</v-btn>
        </section>

        <v-row class="metric-grid" dense>
          <v-col cols="12" md="5"><v-card class="metric-card featured" color="primary"><v-card-text><div class="metric-top"><span>This month</span><v-icon size="18">mdi-arrow-top-right-circle-outline</v-icon></div><strong class="metric-value">{{ money(summary.total) }}</strong><div class="metric-foot"><span class="trend">↗ {{ Math.abs(summary.change_vs_previous_month) }}%</span><span>vs last month</span></div><div class="mini-bars"><i v-for="(bar, index) in miniBars" :key="index" :style="{ height: `${bar}%` }"></i></div></v-card-text></v-card></v-col>
          <v-col cols="12" sm="6" md="4"><v-card class="metric-card"><v-card-text><div class="metric-top"><span>Average expense</span><v-icon size="18" color="primary">mdi-chart-timeline-variant</v-icon></div><strong class="metric-value">{{ money(summary.average) }}</strong><div class="metric-foot"><span>Per transaction</span></div><div class="metric-rule"><i :style="{ width: `${Math.min(summary.average / 100, 100)}%` }"></i></div></v-card-text></v-card></v-col>
          <v-col cols="12" sm="6" md="3"><v-card class="metric-card"><v-card-text><div class="metric-top"><span>Entries this month</span><v-icon size="18" color="secondary">mdi-pound</v-icon></div><strong class="metric-value">{{ summary.count }}</strong><div class="metric-foot"><span>Keep tracking to see patterns</span></div><div class="entry-dots"><i v-for="n in Math.min(summary.count, 12)" :key="n"></i></div></v-card-text></v-card></v-col>
        </v-row>

        <v-row id="insights" ref="analytics" class="analytics-grid" dense>
          <v-col cols="12" md="5"><v-card class="panel category-panel"><v-card-text><div class="panel-heading"><div><p class="eyebrow">Spending mix</p><h2>Where it goes</h2></div><v-btn icon="mdi-dots-horizontal" variant="text" size="small" /></div><div class="category-content"><div class="donut" :style="donutStyle"><div><strong>{{ money(summary.total) }}</strong><span>total spent</span></div></div><div class="legend"><div v-for="item in categories.slice(0, 4)" :key="item.category" class="legend-row"><span class="legend-label"><i :class="categoryClass(item.category)"></i>{{ item.category }}</span><strong>{{ money(item.total) }}</strong></div></div></div><div class="panel-note"><span>Top category</span><strong>{{ categories[0]?.category || 'No entries yet' }}</strong><span class="note-amount">{{ money(categories[0]?.total || 0) }}</span></div></v-card-text></v-card></v-col>
          <v-col cols="12" md="7"><v-card class="panel trend-panel"><v-card-text><div class="panel-heading"><div><p class="eyebrow">Last 6 months</p><h2>Spending trend</h2></div><v-select class="chart-select" :items="['Monthly', 'Weekly']" model-value="Monthly" density="compact" variant="solo" flat hide-details /></div><div class="chart-wrap"><div class="y-labels"><span>₹{{ compact(maxMonthly * 1.1) }}</span><span>₹{{ compact(maxMonthly * .73) }}</span><span>₹{{ compact(maxMonthly * .36) }}</span><span>₹0</span></div><div class="chart"><div class="grid-line line-1"></div><div class="grid-line line-2"></div><div class="grid-line line-3"></div><div class="grid-line line-4"></div><div class="bars"><div v-for="month in monthly" :key="month.month" class="bar-group"><div class="bar-value">{{ compact(month.total) }}</div><div class="bar" :style="{ height: `${Math.max((month.total / maxMonthly) * 100, 5)}%` }"></div><span>{{ monthLabel(month.month) }}</span></div></div></div></div></v-card-text></v-card></v-col>
        </v-row>

        <section id="transactions" ref="transactions" class="transactions-section"><div class="section-heading"><div><p class="eyebrow">Your activity</p><h2>Recent expenses</h2></div><div class="section-actions"><v-btn v-if="expenses.length" variant="text" color="primary" append-icon="mdi-arrow-top-right" @click="exportCsv">Export CSV</v-btn><v-btn color="primary" prepend-icon="mdi-plus" @click="openAddModal">Add expense</v-btn></div></div><v-row class="filters" dense><v-col cols="12" md="6"><v-text-field v-model="filters.search" prepend-inner-icon="mdi-magnify" placeholder="Search expenses..." clearable /></v-col><v-col cols="6" md="3"><v-select v-model="filters.category" :items="[{ title: 'All categories', value: 'all' }, ...meta.categories.map((item) => ({ title: item, value: item }))]" /></v-col><v-col cols="6" md="3"><v-select v-model="filters.sort" :items="[{ title: 'Newest first', value: 'newest' }, { title: 'Oldest first', value: 'oldest' }]" /></v-col></v-row><v-card class="table-card"><v-data-table :headers="headers" :items="displayedExpenses" item-value="id" density="comfortable" hover :items-per-page="-1" hide-default-footer><template #item.title="{ item }"><div class="expense-name"><v-avatar :class="['expense-icon', categoryClass(item.category)]" rounded="lg" size="34"><span>{{ categoryEmoji(item.category) }}</span></v-avatar><div><strong>{{ item.title }}</strong><span v-if="item.notes">{{ item.notes }}</span></div></div></template><template #item.category="{ item }"><v-chip size="small" variant="tonal">{{ item.category }}</v-chip></template><template #item.date="{ item }">{{ formatDate(item.date) }}</template><template #item.payment_method="{ item }"><span class="payment"><v-icon size="16">{{ paymentIcon(item.payment_method) }}</v-icon>{{ item.payment_method }}</span></template><template #item.amount="{ item }"><strong>{{ money(item.amount) }}</strong></template><template #item.actions="{ item }"><v-btn icon="mdi-dots-horizontal" variant="text" size="small" @click="openEditModal(item)" /></template><template #no-data><div class="empty-state"><v-icon size="30" color="primary">mdi-receipt-text-outline</v-icon><strong>{{ filters.search || filters.category !== 'all' ? 'No matching expenses' : 'Your ledger is empty' }}</strong><span>{{ filters.search || filters.category !== 'all' ? 'Try changing your filters.' : 'Add your first expense to start seeing your spending patterns.' }}</span><v-btn v-if="!filters.search && filters.category === 'all'" color="primary" size="small" @click="openAddModal">Add your first expense</v-btn><v-btn v-else variant="text" size="small" @click="clearFilters">Clear filters</v-btn></div></template></v-data-table></v-card><div class="table-footer">Showing <strong>{{ displayedExpenses.length }}</strong> of {{ expenses.length }} expenses</div></section>
        <footer><span>© {{ new Date().getFullYear() }} Pocketwise</span><span>Built for better money days <b>✦</b></span></footer>
      </v-container>
      <v-snackbar v-model="feedback.visible" :color="feedback.type === 'error' ? 'error' : 'primary'" timeout="3500">{{ feedback.message }}<template #actions><v-btn variant="text" @click="feedback.visible = false">Close</v-btn></template></v-snackbar>
    </v-main>

    <v-dialog v-model="modalOpen" max-width="520" persistent><v-card class="expense-modal"><v-card-title class="modal-header"><div><p class="eyebrow">{{ editingExpense ? 'Update entry' : 'New entry' }}</p><h2>{{ editingExpense ? 'Edit expense' : 'Add an expense' }}</h2></div><v-btn icon="mdi-close" variant="text" @click="closeModal" /></v-card-title><v-card-text><v-form @submit.prevent="saveExpense"><v-text-field v-model.trim="form.title" label="What was it for?" required maxlength="120" /><v-row dense><v-col cols="12" sm="6"><v-text-field v-model.number="form.amount" label="Amount" prefix="₹" required min="0.01" step="0.01" type="number" /></v-col><v-col cols="12" sm="6"><v-text-field v-model="form.date" label="Date" required type="date" /></v-col></v-row><v-row dense><v-col cols="12" sm="6"><v-select v-model="form.category" label="Category" :items="meta.categories" required /></v-col><v-col cols="12" sm="6"><v-select v-model="form.payment_method" label="Payment method" :items="meta.payment_methods" required /></v-col></v-row><v-textarea v-model.trim="form.notes" label="Notes (optional)" maxlength="500" rows="3" /><p v-if="error" class="form-error">{{ error }}</p><div class="modal-actions"><v-btn v-if="editingExpense" color="error" variant="text" type="button" @click="removeExpense">Delete</v-btn><v-spacer /><v-btn variant="text" type="button" @click="closeModal">Cancel</v-btn><v-btn color="primary" type="submit">{{ editingExpense ? 'Save changes' : 'Add expense' }}</v-btn></div></v-form></v-card-text></v-card></v-dialog>
  </v-app>
  <v-app v-else class="auth-app" :theme="darkMode ? 'pocketwiseDark' : 'pocketwise'">
    <main class="auth-page">
      <section class="auth-art">
        <div class="auth-art-content"><div class="brand"><div class="brand-mark">P</div><div><strong>Pocketwise</strong><span>personal finance</span></div></div><div class="auth-quote"><span class="quote-mark">“</span><h1>Make space for<br /><em>what matters.</em></h1><p>Simple tracking for a calmer relationship with your money.</p></div><div class="auth-art-footer"><span>Private by default</span><span>✦</span><span>Built for better money days</span></div></div>
      </section>
      <section class="auth-form-area">
        <div class="auth-form-wrap"><div class="auth-mobile-brand"><div class="brand-mark">P</div><strong>Pocketwise</strong></div><div class="auth-heading"><p class="eyebrow">{{ authMode === 'login' ? 'Welcome back' : 'Start your ledger' }}</p><h2>{{ authMode === 'login' ? 'Good to see you.' : 'Create your space.' }}</h2><p>{{ authMode === 'login' ? 'Sign in to keep your money in focus.' : 'A clear view of your spending starts here.' }}</p></div><v-form @submit.prevent="submitAuth"><v-text-field v-if="authMode === 'register'" v-model.trim="authForm.name" label="Your name" prepend-inner-icon="mdi-account-outline" autocomplete="name" required /><v-text-field v-model.trim="authForm.email" label="Email address" prepend-inner-icon="mdi-email-outline" type="email" autocomplete="email" required /><v-text-field v-model="authForm.password" label="Password" prepend-inner-icon="mdi-lock-outline" :append-inner-icon="showPassword ? 'mdi-eye-off-outline' : 'mdi-eye-outline'" :type="showPassword ? 'text' : 'password'" :autocomplete="authMode === 'login' ? 'current-password' : 'new-password'" :hint="authMode === 'register' ? 'Use at least 8 characters' : ''" persistent-hint required @click:append-inner="showPassword = !showPassword" /><v-alert v-if="authError" class="auth-alert" type="error" variant="tonal" density="comfortable">{{ authError }}</v-alert><v-btn class="auth-submit" color="primary" size="large" block type="submit" :loading="authLoading">{{ authMode === 'login' ? 'Sign in' : 'Create account' }}<v-icon end>mdi-arrow-right</v-icon></v-btn></v-form><p class="auth-switch">{{ authMode === 'login' ? 'New to Pocketwise?' : 'Already have an account?' }} <button type="button" @click="switchAuthMode">{{ authMode === 'login' ? 'Create an account' : 'Sign in instead' }}</button></p><p class="auth-privacy"><v-icon size="14">mdi-shield-check-outline</v-icon> Your data stays in your private account.</p></div>
      </section>
    </main>
  </v-app>
</template>

<script>
const emptyForm = () => ({ title: '', amount: null, category: 'Food & dining', date: new Date().toISOString().slice(0, 10), payment_method: 'Debit card', notes: '' })

export default {
  name: 'App',
  data() { return { authenticated: false, loading: false, activeSection: 'overview', scrollSpyStarted: false, feedback: { visible: false, message: '', type: 'success' }, authMode: 'login', authForm: { name: '', email: '', password: '' }, authLoading: false, authError: '', showPassword: false, token: localStorage.getItem('pocketwise_token') || '', expenses: [], categories: [], monthly: [], summary: { total: 0, average: 0, count: 0, change_vs_previous_month: 0 }, meta: { categories: [], payment_methods: [] }, profile: { name: '', account_label: '', email: '' }, profileForm: { name: '', account_label: '' }, profileMenuOpen: false, profileSaving: false, profileError: '', filters: { search: '', category: 'all', sort: 'newest' }, modalOpen: false, editingExpense: null, form: emptyForm(), error: '', darkMode: false, drawerOpen: true, isMobile: false, headers: [{ title: 'Expense', key: 'title', sortable: false }, { title: 'Category', key: 'category', sortable: false }, { title: 'Date', key: 'date', sortable: false }, { title: 'Payment method', key: 'payment_method', sortable: false }, { title: 'Amount', key: 'amount', align: 'end', sortable: false }, { title: '', key: 'actions', align: 'end', sortable: false }] } },
  computed: {
    greeting() { const hour = new Date().getHours(); return hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening' }, firstName() { return this.profile.name.split(' ')[0] || 'there' }, initials() { return this.profile.name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0].toUpperCase()).join('') || '?' },
    displayedExpenses() { const rows = this.expenses.filter((expense) => `${expense.title} ${expense.notes}`.toLowerCase().includes(this.filters.search.toLowerCase()) && (this.filters.category === 'all' || expense.category === this.filters.category)); return this.filters.sort === 'oldest' ? [...rows].reverse() : rows },
    maxMonthly() { return Math.max(...this.monthly.map((month) => month.total), 1) },
    donutStyle() { const colors = ['#e87568', '#d6a85f', '#7fa99a', '#888ed5', '#78a8a5']; let position = 0; const parts = this.categories.slice(0, 5).map((item, index) => { const start = position; position += item.percentage; return `${colors[index]} ${start}% ${position}%` }); return { background: `conic-gradient(${parts.join(', ') || '#dfe1ec 0 100%'})` } },
    miniBars() { return this.monthly.length ? this.monthly.map((month) => Math.max(12, (month.total / this.maxMonthly) * 100)) : [20, 35, 25, 45, 30, 60, 42] },
  },
  async mounted() { this.isMobile = window.innerWidth <= 680; window.addEventListener('resize', this.handleResize); if (this.token) { try { await this.request('/api/auth/me'); this.authenticated = true; await this.loadData(); this.startScrollSpy() } catch { this.clearSession() } } },
  beforeUnmount() { window.removeEventListener('resize', this.handleResize); this.stopScrollSpy() },
  methods: {
    async request(url, options = {}) { const headers = { 'Content-Type': 'application/json', ...(options.headers || {}) }; if (this.token) headers.Authorization = `Bearer ${this.token}`; const response = await fetch(url, { ...options, headers }); if (!response.ok) throw new Error((await response.json()).detail || 'Something went wrong'); return response.status === 204 ? null : response.json() },
    async loadData() { this.loading = true; try { [this.expenses, this.summary, this.categories, this.monthly, this.meta, this.profile] = await Promise.all([this.request('/api/expenses'), this.request('/api/analytics/summary'), this.request('/api/analytics/categories'), this.request('/api/analytics/monthly'), this.request('/api/meta'), this.request('/api/profile')]) } catch (error) { if (error.message.includes('Authentication')) this.clearSession(); else { this.error = 'Connect the API to load your expenses.'; this.notify(this.error, 'error'); console.error(error) } } finally { this.loading = false } },
    money(value) { return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value || 0) }, compact(value) { return value >= 1000 ? `${(value / 1000).toFixed(1)}k` : Math.round(value) }, formatDate(value) { return new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(`${value}T00:00:00`)) }, monthLabel(value) { return new Intl.DateTimeFormat('en-US', { month: 'short' }).format(new Date(`${value}-01T00:00:00`)) },
    categoryEmoji(category) { return { 'Food & dining': '✦', Transport: '↗', Shopping: '◇', Bills: '▤', Health: '+', Entertainment: '♫', Other: '•' }[category] || '•' }, categoryClass(category) { return `color-${(category || 'other').toLowerCase().replace(/[^a-z]+/g, '-')}` }, paymentIcon(method) { return method === 'Cash' ? 'mdi-cash' : method === 'Bank transfer' ? 'mdi-bank-transfer' : method === 'Digital wallet' ? 'mdi-wallet-outline' : 'mdi-credit-card-outline' },
    openAddModal() { this.editingExpense = null; this.form = emptyForm(); this.error = ''; this.modalOpen = true }, openEditModal(expense) { this.editingExpense = expense; this.form = { ...expense }; this.error = ''; this.modalOpen = true }, closeModal() { this.modalOpen = false }, openProfileMenu() { this.profileMenuOpen = !this.profileMenuOpen; if (this.profileMenuOpen) { this.profileForm = { name: this.profile.name, account_label: this.profile.account_label }; this.profileError = '' } },
    async saveExpense() { try { this.error = ''; const url = this.editingExpense ? `/api/expenses/${this.editingExpense.id}` : '/api/expenses'; await this.request(url, { method: this.editingExpense ? 'PUT' : 'POST', body: JSON.stringify(this.form) }); this.closeModal(); this.notify(this.editingExpense ? 'Expense updated' : 'Expense added'); await this.loadData() } catch (error) { this.error = error.message; this.notify(error.message, 'error') } },
    async removeExpense() { if (!this.editingExpense || !window.confirm('Delete this expense?')) return; try { await this.request(`/api/expenses/${this.editingExpense.id}`, { method: 'DELETE' }); this.closeModal(); this.notify('Expense deleted'); await this.loadData() } catch (error) { this.error = error.message; this.notify(error.message, 'error') } },
    switchAuthMode() { this.authMode = this.authMode === 'login' ? 'register' : 'login'; this.authError = '' }, async submitAuth() { this.authLoading = true; this.authError = ''; try { const endpoint = this.authMode === 'login' ? '/api/auth/login' : '/api/auth/register'; const response = await this.request(endpoint, { method: 'POST', body: JSON.stringify(this.authForm) }); this.token = response.token; localStorage.setItem('pocketwise_token', this.token); this.authenticated = true; await this.loadData(); this.startScrollSpy() } catch (error) { this.authError = error.message } finally { this.authLoading = false } }, clearSession() { this.stopScrollSpy(); this.token = ''; localStorage.removeItem('pocketwise_token'); this.authenticated = false; this.profile = { name: '', account_label: '' } }, async logout() { try { await this.request('/api/auth/logout', { method: 'POST' }) } finally { this.profileMenuOpen = false; this.clearSession() } }, async saveProfile() { this.profileSaving = true; try { this.profileError = ''; this.profile = await this.request('/api/profile', { method: 'PUT', body: JSON.stringify(this.profileForm) }); this.profileMenuOpen = false; this.notify('Profile updated') } catch (error) { this.profileError = error.message; this.notify(error.message, 'error') } finally { this.profileSaving = false } }, async exportCsv() { const response = await fetch('/api/expenses/export', { headers: { Authorization: `Bearer ${this.token}` } }); if (!response.ok) throw new Error('Could not export expenses'); const blob = await response.blob(); const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'expenses.csv'; link.click(); URL.revokeObjectURL(link.href); this.notify('CSV exported') }, clearFilters() { this.filters.search = ''; this.filters.category = 'all' }, notify(message, type = 'success') { this.feedback = { visible: true, message, type } }, scrollToSection(section) { this.activeSection = section; if (this.isMobile) this.drawerOpen = false; if (section === 'overview') { window.scrollTo({ top: 0, behavior: 'smooth' }); return } this.$nextTick(() => { const target = document.getElementById(section); if (!target) return; const headerHeight = document.querySelector('.header-bar')?.getBoundingClientRect().height || (this.isMobile ? 65 : 87); const top = target.getBoundingClientRect().top + window.scrollY - headerHeight - 18; window.scrollTo({ top: Math.max(top, 0), behavior: 'smooth' }); window.setTimeout(() => this.updateActiveSection(), 450) }) }, scrollToTransactions() { this.scrollToSection('transactions') }, focusAnalytics() { this.scrollToSection('insights') }, startScrollSpy() { if (this.scrollSpyStarted) return; this.scrollSpyStarted = true; this.updateActiveSection(); window.addEventListener('scroll', this.updateActiveSection, { passive: true }) }, stopScrollSpy() { if (!this.scrollSpyStarted) return; window.removeEventListener('scroll', this.updateActiveSection); this.scrollSpyStarted = false }, updateActiveSection() { if (!this.authenticated) return; const analytics = document.getElementById('insights'); const transactions = document.getElementById('transactions'); if (!analytics || !transactions) return; const scrollPosition = window.scrollY + (this.isMobile ? 110 : 145); const analyticsTop = analytics.getBoundingClientRect().top + window.scrollY; const transactionsTop = transactions.getBoundingClientRect().top + window.scrollY; this.activeSection = scrollPosition >= transactionsTop ? 'transactions' : scrollPosition >= analyticsTop ? 'insights' : 'overview' }, toggleTheme() { this.darkMode = !this.darkMode; document.documentElement.classList.toggle('dark', this.darkMode) }, handleResize() { this.isMobile = window.innerWidth <= 680; if (!this.isMobile) this.drawerOpen = true },
  },
}
</script>
